import {
  aboutGalleryImages,
  aboutGalleryFull,
  aboutGalleryPreview,
  aboutGallerySize,
} from '../../data/aboutGallery';

export function initScript() {
  function onDOMContentLoaded() {
    console.log('DOM fully loaded and parsed');
    // Your script logic here
    // Array of image filenames
    const imageFilenames = aboutGalleryImages;

    // Function to shuffle an array
    function shuffle(array) {
      for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
      }
      return array;
    }

    // Shuffle the image filenames
    const shuffledFilenames = shuffle(imageFilenames);
    // Get the scroll-container div
    const container = document.getElementById('showcaseimages');

    // Dynamically create img elements and append them to the container
    shuffledFilenames.forEach((filename, index) => {
      const img = document.createElement('img');
      const [width, height] = aboutGallerySize(filename);
      img.src = aboutGalleryPreview(filename);
      img.dataset.fullSrc = aboutGalleryFull(filename);
      img.width = width;
      img.height = height;
      img.decoding = 'async';
      img.loading = index < 2 || index === shuffledFilenames.length - 1 ? 'eager' : 'lazy';
      container.appendChild(img);
    });

  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', onDOMContentLoaded);
  } else {
    // The DOMContentLoaded event has already fired
    onDOMContentLoaded();
  }
}
